/*Table structure for table `barang_awal` */

DROP TABLE IF EXISTS `barang_awal`;

CREATE TABLE `barang_awal` (
  `idbarang` varchar(255) DEFAULT NULL,
  `kdbarang` varchar(255) DEFAULT NULL,
  `namabarang` varchar(255) DEFAULT NULL,
  `idkategori` varchar(255) DEFAULT NULL,
  `kdakun` varchar(255) DEFAULT NULL,
  `stok` double DEFAULT NULL,
  `fotobarang` varchar(255) DEFAULT NULL,
  `hargabeli` double DEFAULT NULL,
  `hargajualasli` double DEFAULT NULL,
  `hargajualdiskon` double DEFAULT NULL,
  `statusaktif` varchar(255) DEFAULT NULL,
  `inserted_date` timestamp NULL DEFAULT NULL,
  `updated_date` timestamp NULL DEFAULT NULL,
  `idjenisbarang` varchar(255) DEFAULT NULL,
  `jenisbonuspenjualan` varchar(255) DEFAULT NULL,
  `persenbonuspenjualan` varchar(255) DEFAULT NULL,
  `jumlahbonuspenjualan` double DEFAULT NULL,
  `jenisbonustagihan` varchar(255) DEFAULT NULL,
  `persenbonustagihan` varchar(255) DEFAULT NULL,
  `jumlahbonustagihan` double DEFAULT NULL,
  `stokminimum` double DEFAULT NULL,
  `hpp` double DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

/*Data for the table `barang_awal` */

